(()=>{'use strict';
const catalog=JSON.parse(document.getElementById('prototype-catalog').textContent),locales=JSON.parse(document.getElementById('site-locales').textContent),grid=document.getElementById('prototype-grid'),shell=document.getElementById('catalog-shell'),player=document.getElementById('player'),stage=document.getElementById('player-stage'),loading=document.getElementById('player-loading'),back=document.getElementById('return-catalog'),fullscreen=document.getElementById('fullscreen');
const storageKey='olga-prototypes-language';let lang='ru';try{const saved=localStorage.getItem(storageKey);if(locales[saved])lang=saved}catch(e){}
let frame=null,active=null,returnId=null,scrollY=0,sessionHash=false,timer,loadTimer,toastKey=null;
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
const t=key=>locales[lang][key]??locales.ru[key]??key;
function text(value,fallback=''){return typeof value==='string'?value:value?.[lang]??value?.ru??value?.en??fallback}
function el(tag,className,content){const node=document.createElement(tag);if(className)node.className=className;if(content!==undefined)node.textContent=content;return node}
function localURL(file){const url=new URL(file,document.baseURI);if(!['http:','https:','file:'].includes(url.protocol)||url.protocol!==location.protocol||url.host!==location.host)throw Error('Prototype must be hosted on this site');return url.href}
function toast(key){toastKey=key;const box=document.getElementById('toast');box.textContent=t(key);box.classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>{box.classList.remove('visible');toastKey=null},4000)}
function renderCards(){grid.replaceChildren();for(const p of catalog){const link=el('a','prototype-card');try{link.href=localURL(p.files?.[lang]||p.file)}catch(e){continue}link.dataset.prototype=p.id;link.setAttribute('aria-label',t('play')+' '+text(p.title));const picture=el('div','card-picture'),image=el('img');image.loading=grid.childElementCount?'lazy':'eager';image.src=p.image;image.alt=t('preview')+' '+text(p.title);image.width=1100;image.height=614;image.decoding='async';picture.append(image,el('span','card-badge',t('ready')));if(p.languages?.length){const badge=el('span','card-languages',p.languages.map(code=>code.toUpperCase()).join(' / '));badge.title=t('gameLanguages')+': '+p.languages.map(code=>t(code==='ru'?'russian':'english')).join(', ');picture.append(badge)}const tags=el('div','card-tags');for(const tag of Array.isArray(p.tags)?p.tags:p.tags?.[lang]||p.tags?.ru||[])tags.append(el('span','',tag));picture.append(tags);const body=el('div','card-body'),titleLine=el('div','card-title-line');titleLine.append(el('h3','card-title',text(p.title)));if(p.version)titleLine.append(el('span','version','v'+p.version));body.append(el('p','card-category',text(p.category,t('category'))),titleLine,el('p','card-description',text(p.description)));const icon=el('span','card-arrow');icon.innerHTML=arrow;body.append(icon);link.append(picture,body);link.addEventListener('click',event=>{if(event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;event.preventDefault();returnId=p.id;sessionHash=true;location.hash='play/'+encodeURIComponent(p.id)});grid.append(link)}const count=grid.querySelectorAll('a.prototype-card').length;const noun=lang==='en'?(count===1?'prototype':'prototypes'):(count%10===1&&count%100!==11?'прототип':count%10>=2&&count%10<=4&&(count%100<12||count%100>14)?'прототипа':'прототипов');document.getElementById('collection-count').textContent=String(count).padStart(2,'0')+' '+noun;if(count<2){const empty=el('div','prototype-card placeholder'),inner=el('div','placeholder-inner'),symbol=el('div','placeholder-symbol');symbol.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4v16M4 12h16"/></svg>';inner.append(symbol,el('p','placeholder-eyebrow',t('coming')),el('h3','',t('placeholderTitle')),el('p','',t('placeholderText')));empty.append(inner);grid.append(empty)}}
function renderFullscreen(){const on=!!document.fullscreenElement;fullscreen.setAttribute('aria-label',t(on?'exitFullscreen':'fullscreen'));fullscreen.title=fullscreen.getAttribute('aria-label');fullscreen.querySelector('span').textContent=t(on?'collapse':'fullscreen')}
function renderLanguage(){document.documentElement.lang=lang;for(const node of document.querySelectorAll('[data-i18n]'))node.textContent=t(node.dataset.i18n);for(const node of document.querySelectorAll('[data-i18n-aria]'))node.setAttribute('aria-label',t(node.dataset.i18nAria));for(const node of document.querySelectorAll('[data-i18n-title]'))node.title=t(node.dataset.i18nTitle);for(const node of document.querySelectorAll('[data-language]'))node.setAttribute('aria-pressed',String(node.dataset.language===lang));document.querySelector('meta[name="description"]').content=t('pageDescription');const p=catalog.find(item=>item.id===active);document.title=p?text(p.title)+' — '+t('author'):t('pageTitle');if(p){document.getElementById('player-title').textContent=text(p.title);if(frame)frame.title=text(p.title)+' — '+t('frame')}if(toastKey)document.getElementById('toast').textContent=t(toastKey);renderCards();renderFullscreen()}
for(const button of document.querySelectorAll('[data-language]'))button.addEventListener('click',()=>{const next=button.dataset.language;if(!locales[next]||next===lang)return;lang=next;try{localStorage.setItem(storageKey,lang)}catch(e){}renderLanguage()});
function close(){if(!active)return;frame?.remove();frame=null;active=null;clearTimeout(loadTimer);player.hidden=true;shell.inert=false;shell.removeAttribute('aria-hidden');document.body.classList.remove('playing');document.title=t('pageTitle');window.scrollTo(0,scrollY);Array.from(grid.querySelectorAll('a.prototype-card')).find(node=>node.dataset.prototype===returnId)?.focus({preventScroll:true});if(document.fullscreenElement)document.exitFullscreen().catch(()=>{})}
function open(p){if(active===p.id)return;let src;try{src=localURL(p.files?.[lang]||p.file)}catch(e){toast('invalidPath');return}if(!active)scrollY=window.scrollY;frame?.remove();active=p.id;shell.inert=true;shell.setAttribute('aria-hidden','true');player.hidden=false;document.body.classList.add('playing');document.getElementById('player-title').textContent=text(p.title);document.title=text(p.title)+' — '+t('author');loading.classList.remove('loaded');frame=document.createElement('iframe');frame.title=text(p.title)+' — '+t('frame');frame.allow='autoplay; fullscreen; gamepad';frame.allowFullscreen=true;frame.referrerPolicy='no-referrer';frame.src=src;const current=frame;frame.addEventListener('load',()=>{if(current!==frame)return;clearTimeout(loadTimer);try{if(current.contentDocument?.title==='Error response'){loading.classList.add('loaded');toast('missingFile');return}}catch(e){}loading.classList.add('loaded');current.focus()},{once:true});stage.append(frame);back.focus({preventScroll:true});clearTimeout(loadTimer);loadTimer=setTimeout(()=>{if(current===frame){loading.classList.add('loaded');toast('slowLoad')}},20000)}
function route(){let id;try{id=location.hash.startsWith('#play/')?decodeURIComponent(location.hash.slice(6)):null}catch(e){id=null}const p=catalog.find(item=>item.id===id);if(p)open(p);else{close();if(id)toast('missingGame')}}
back.addEventListener('click',()=>{if(sessionHash){sessionHash=false;history.back()}else{history.replaceState(null,'',location.pathname+location.search);close()}});window.addEventListener('hashchange',route);window.addEventListener('popstate',route);fullscreen.hidden=!player.requestFullscreen;fullscreen.addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await player.requestFullscreen()}catch(e){toast('fullscreenUnavailable')}});document.addEventListener('fullscreenchange',renderFullscreen);renderLanguage();route();
})();
